#include <iostream>
#include <string>

struct Order { int id; int item_count; };
bool valid_for_storage(const Order& order) { return order.id > 0 && order.item_count >= 0; }
int main() {
    const Order order{103, 4};
    std::cout << std::boolalpha << valid_for_storage(order) << '\n';
}
